CREATE TABLE provider_observations(id uuid PRIMARY KEY,intent_id uuid NOT NULL,intent_version integer NOT NULL,environment text NOT NULL CHECK(environment='sandbox'),order_id text NOT NULL,authorization_id text,capture_id text,amount_minor bigint NOT NULL CHECK(amount_minor>0),currency text NOT NULL CHECK(currency='USD'),payee_id text NOT NULL,order_status text NOT NULL,authorization_status text NOT NULL,capture_status text NOT NULL,normalized_status text NOT NULL,debug_id text,observed_at timestamptz NOT NULL,FOREIGN KEY(intent_id,intent_version) REFERENCES intent_versions);
CREATE INDEX provider_observations_intent ON provider_observations(intent_id,observed_at DESC);
CREATE TRIGGER immutable_provider_observation BEFORE UPDATE OR DELETE ON provider_observations FOR EACH ROW EXECUTE FUNCTION reject_immutable_change();
